const h  = mix(w1, w2, 0.5);
const foam = pow(h, 8);
return hsv(mix(0.55, 0.62, h), mix(0.9, 0.1, foam), mix(0.4, 1.0, h));`},{id:"candle",name:"Candle",desc:"Warm gentle flicker of a single candle flame",preview:"radial-gradient(ellipse at 50% 80%,#ffffff 0%,#ffee88 10%,#ff7700 40%,#220000 100%)",code:`// @param flicker float 3.0 0.5 8.0
